import os
os.environ.setdefault('OMP_NUM_THREADS','2')
import torch,nvdiffrast.torch as dr,numpy as np,trimesh,json,cv2
from PIL import Image,ImageDraw
p='/work/inputs/';m=trimesh.load(p+'object_mesh.glb',force='scene',process=False).to_geometry();v=torch.tensor(np.array(m.vertices),dtype=torch.float32,device='cuda');f=torch.tensor(np.array(m.faces),dtype=torch.int32,device='cuda');col=torch.tensor(m.visual.to_color().vertex_colors[:,:3].copy()/255,dtype=torch.float32,device='cuda');ctx=dr.RasterizeCudaContext();c=json.load(open(p+'camera.json'));K=np.array(c['K']);a=np.load(p+'reconstruction.npz');T=np.linalg.inv(c['T_world_cam'])@a['T_world_mesh'];cap=cv2.VideoCapture(p+'video.mp4');canvas=Image.new('RGB',(1800,1200),'white');draw=ImageDraw.Draw(canvas)
for j,i in enumerate([0,200,500,700,900,987]):
 P=torch.tensor(T[i],device='cuda',dtype=torch.float32);xyz=v@P[:3,:3].T+P[:3,3];u=K[0,0]*xyz[:,0]+K[0,2]*xyz[:,2];vv=K[1,1]*xyz[:,1]+K[1,2]*xyz[:,2];clip=torch.stack([2*u/1536-xyz[:,2],2*vv/1152-xyz[:,2],xyz[:,2]*.99-.01,xyz[:,2]],-1)[None];rast,_=dr.rasterize(ctx,clip,f,resolution=[1152,1536]);co,_=dr.interpolate(col[None],rast,f);rgb=(co[0]*255).clamp(0,255).byte().cpu().numpy();ma=(rast[0,:,:,3]>0).cpu().numpy();cap.set(cv2.CAP_PROP_POS_FRAMES,i);_,im=cap.read();im=cv2.cvtColor(im,cv2.COLOR_BGR2RGB);im[ma]=(im[ma]*.25+rgb[ma]*.75).astype('uint8');uv=np.array([[0,0,-.45],[0,0,1]])@T[i,:3,:3].T+T[i,:3,3];uv=uv@K.T;uv=uv[:,:2]/uv[:,2:];lo=uv.min(0)-100;hi=uv.max(0)+100;lo=lo.astype(int).clip(0,[1535,1151]);hi=hi.astype(int).clip(0,[1535,1151]);im=im[lo[1]:hi[1],lo[0]:hi[0]];h,w=im.shape[:2];sc=min(600/w,570/h);im=cv2.resize(im,(round(w*sc),round(h*sc)));canvas.paste(Image.fromarray(im),((j%3)*600,(j//3)*600+30));draw.text(((j%3)*600+5,(j//3)*600+5),str(i),fill='black')
canvas.save('/work/outputs/baseline_render.jpg')
